```python
# Command interface
class Command(ABC):
    @abstractmethod
    def execute(self):
        pass

    @abstractmethod
    def undo(self):
        pass

# Receiver
class Light:
    def __init__(self, location):
        self.location = location
        self.is_on = False

    def turn_on(self):
        self.is_on = True
        return f"💡 {self.location} light is ON"

    def turn_off(self):
        self.is_on = False
        return f"💡 {self.location} light is OFF"

# Concrete commands
class LightOnCommand(Command):
    def __init__(self, light: Light):
        self.light = light

    def execute(self):
        return self.light.turn_on()

    def undo(self):
        return self.light.turn_off()

class LightOffCommand(Command):
    def __init__(self, light: Light):
        self.light = light

    def execute(self):
        return self.light.turn_off()

    def undo(self):
        return self.light.turn_on()

# More receivers and commands
class TV:
    def __init__(self):
        self.is_on = False
        self.volume = 10

    def turn_on(self):
        self.is_on = True
        return "📺 TV is ON"

    def turn_off(self):
        self.is_on = False
        return "📺 TV is OFF"

    def volume_up(self):
        self.volume = min(100, self.volume + 10)
        return f"🔊 Volume: {self.volume}"

    def volume_down(self):
        self.volume = max(0, self.volume - 10)
        return f"🔉 Volume: {self.volume}"

class TVOnCommand(Command):
    def __init__(self, tv: TV):
        self.tv = tv

    def execute(self):
        return self.tv.turn_on()

    def undo(self):
        return self.tv.turn_off()
