class VolumeUpCommand(Command):
    def __init__(self, tv: TV):
        self.tv = tv

    def execute(self):
        return self.tv.volume_up()

    def undo(self):
        return self.tv.volume_down()

# Invoker
class RemoteControl:
    def __init__(self):
        self.history = []

    def execute_command(self, command: Command):
        result = command.execute()
        self.history.append(command)
        return result

    def undo_last(self):
        if self.history:
            command = self.history.pop()
            return command.undo()
        return "❌ Nothing to undo"

# Demo
print("\n🔍 Testing Command Pattern:")
living_room_light = Light("Living Room")
bedroom_light = Light("Bedroom")
tv = TV()

remote = RemoteControl()

print("\n1. Executing commands:")
print(f"   {remote.execute_command(LightOnCommand(living_room_light))}")
print(f"   {remote.execute_command(LightOnCommand(bedroom_light))}")
print(f"   {remote.execute_command(TVOnCommand(tv))}")
print(f"   {remote.execute_command(VolumeUpCommand(tv))}")
print(f"   {remote.execute_command(VolumeUpCommand(tv))}")

print("\n2. Undo operations:")
print(f"   {remote.undo_last()}")
print(f"   {remote.undo_last()}")
print(f"   {remote.undo_last()}")

# Macro command
print("\n3. Macro Command (Multiple commands at once):")
