# Handler interface
class Handler(ABC):
    def __init__(self):
        self._next_handler = None

    def set_next(self, handler):
        self._next_handler = handler
        return handler

    @abstractmethod
    def handle(self, request):
        if self._next_handler:
            return self._next_handler.handle(request)
        return None

# Concrete handlers
class Level1Support(Handler):
    def handle(self, request):
        if request["priority"] == "low":
            return f"🟢 Level 1 Support: Handled '{request['issue']}'"
        print(f"   ⏭️ Level 1: Passing to Level 2...")
        return super().handle(request)

class Level2Support(Handler):
    def handle(self, request):
        if request["priority"] == "medium":
            return f"🟡 Level 2 Support: Handled '{request['issue']}'"
        print(f"   ⏭️ Level 2: Passing to Level 3...")
        return super().handle(request)

class Level3Support(Handler):
    def handle(self, request):
        if request["priority"] == "high":
            return f"🟠 Level 3 Support: Handled '{request['issue']}'"
        print(f"   ⏭️ Level 3: Passing to Manager...")
        return super().handle(request)
