class ManagerSupport(Handler):
    def handle(self, request):
        return f"🔴 Manager: Personally handling '{request['issue']}'"

# Demo
print("\n🔍 Testing Chain of Responsibility Pattern:")

# Build the chain
level1 = Level1Support()
level2 = Level2Support()
level3 = Level3Support()
manager = ManagerSupport()

level1.set_next(level2).set_next(level3).set_next(manager)

# Test with different priority requests
requests = [
    {"issue": "Password reset", "priority": "low"},
    {"issue": "Software bug", "priority": "medium"},
    {"issue": "Server down", "priority": "high"},
    {"issue": "Critical security breach", "priority": "critical"}
]

for req in requests:
