# Another example: Expense approval
print("\n\n💰 Another Example - Expense Approval Chain:")

class ExpenseHandler(ABC):
    def __init__(self, approval_limit):
        self.approval_limit = approval_limit
        self._next_handler = None

    def set_next(self, handler):
        self._next_handler = handler
        return handler

    @abstractmethod
    def handle(self, amount):
        pass

class TeamLead(ExpenseHandler):
    def handle(self, amount):
        if amount <= self.approval_limit:
            return f"👤 Team Lead: Approved ${amount}"
        if self._next_handler:
            print(f"   ⏭️ Team Lead: Amount ${amount} exceeds limit ${self.approval_limit}, passing up...")
            return self._next_handler.handle(amount)
        return f"❌ Rejected: ${amount}"
