# State interface
class State(ABC):
    @abstractmethod
    def handle(self, context):
        pass

# Context
class OrderContext:
    def __init__(self):
        self._state = NewOrderState()

    def set_state(self, state: State):
        self._state = state

    def get_state_name(self):
        return self._state.__class__.__name__

    def next_state(self):
        self._state.handle(self)

# Concrete states
class NewOrderState(State):
    def handle(self, context):
        print("📦 New Order → Processing...")
        context.set_state(ProcessingState())

class ProcessingState(State):
    def handle(self, context):
        print("⚙️ Processing → Shipped...")
        context.set_state(ShippedState())

class ShippedState(State):
    def handle(self, context):
        print("🚚 Shipped → Delivered...")
        context.set_state(DeliveredState())

class DeliveredState(State):
    def handle(self, context):
        print("✅ Delivered → Order Complete!")
        print("   (No more state changes)")

# Demo
print("\n🔍 Testing State Pattern:")
order = OrderContext()

print(f"\nCurrent state: {order.get_state_name()}")
for i in range(4):
    print(f"\n{i+1}. Advancing state:")
    order.next_state()
    print(f"   Current state: {order.get_state_name()}")

# Another example: Document workflow
print("\n\n📝 Another Example - Document Workflow:")
```

