class DocumentContext:
    def __init__(self, name):
        self.name = name
        self._state = DraftState()
        print(f"📄 Created document: {name}")

    def set_state(self, state):
        self._state = state

    def get_status(self):
        return self._state.__class__.__name__.replace("State", "")

    def submit_for_review(self):
        self._state.submit_for_review(self)

    def approve(self):
        self._state.approve(self)

    def publish(self):
        self._state.publish(self)

    def reject(self):
        self._state.reject(self)

class DocumentState(ABC):
    @abstractmethod
    def submit_for_review(self, doc):
        pass

    @abstractmethod
    def approve(self, doc):
        pass

    @abstractmethod
    def publish(self, doc):
        pass

    @abstractmethod
    def reject(self, doc):
        pass

class DraftState(DocumentState):
    def submit_for_review(self, doc):
        print(f"✅ '{doc.name}' submitted for review")
        doc.set_state(ReviewState())

    def approve(self, doc):
        print("❌ Cannot approve draft directly")

    def publish(self, doc):
        print("❌ Cannot publish draft directly")

    def reject(self, doc):
        print("❌ Cannot reject draft")

class ReviewState(DocumentState):
    def submit_for_review(self, doc):
        print("ℹ️ Already in review")

    def approve(self, doc):
        print(f"✅ '{doc.name}' approved")
        doc.set_state(ApprovedState())

    def publish(self, doc):
        print("❌ Must be approved first")

    def reject(self, doc):
        print(f"❌ '{doc.name}' rejected, back to draft")
        doc.set_state(DraftState())
