# Another example: Game character actions
print("\n🎮 Another Example - Game Character Actions:")

class CharacterAction(ABC):
    """Template for character actions"""

    def perform_action(self):
        print(f"\n{self.get_action_name()}:")
        self.prepare()
        self.execute()
        self.follow_up()
        print()

    @abstractmethod
    def get_action_name(self):
        pass

    @abstractmethod
    def prepare(self):
        pass

    @abstractmethod
    def execute(self):
        pass

    def follow_up(self):
        """Optional hook - default implementation"""
        print("   ✓ Action complete")

class AttackAction(CharacterAction):
    def get_action_name(self):
        return "⚔️ Attack"

    def prepare(self):
        print("   🎯 Taking aim...")

    def execute(self):
        print("   💥 Strike the enemy!")

    def follow_up(self):
        print("   🔊 Battle cry!")
